const raw = $input.first().json.data || $input.first().json.body || '';
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);

const results = [];
const lines = text.split('\n');
let dbid = 1;

for (const line of lines) {
  const match = line.match(/<a\s+id="([^"]+)"\s+href="([^"]+)">([^<]+)<\/a>/i);
  if (match) {
    results.push({
      json: {
        DBID: dbid++,
        id: match[1],
        href: match[2].replace('http://', 'https://'),
        linktext: match[3].trim()
      }
    });
  }
}

return results.slice(0, 233);

const links = $input.all().map(i => i.json.href);
const results = [];

function clean(str) {
  if (!str) return '';
  return str.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function extractEdikt(html) {
  const startIdx = html.indexOf('id="edikt"');
  if (startIdx === -1) return html;
  const openTagEnd = html.indexOf('>', startIdx);
  if (openTagEnd === -1) return html;

  let depth = 1;
  let curr = openTagEnd + 1;
  const divRegex = /<\/?div\b[^>]*>/gi;
  divRegex.lastIndex = curr;
  let m;

  while ((m = divRegex.exec(html)) !== null) {
    if (m[0].toLowerCase().startsWith('</div')) {
      depth--;
    } else {
      depth++;
    }
    if (depth === 0) {
      return html.substring(openTagEnd + 1, m.index);
    }
  }
  return html.substring(openTagEnd + 1);
}

const batchSize = 15;

for (let i = 0; i < links.length; i += batchSize) {
  const batch = links.slice(i, i + batchSize);
  const promises = batch.map(async (url) => {
    try {
      const response = await this.helpers.httpRequest({
        method: 'GET',
        url: url,
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
        },
        timeout: 10000,
        json: false
      });

      const rawHtml = typeof response === 'string' ? response : (response.data || '');
      const rowObj = {};

      // 1. h1 és h2 mezők
      const h1Match = rawHtml.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
      const h2Match = rawHtml.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i);
      rowObj['h1'] = h1Match ? clean(h1Match[1]) : '';
      rowObj['h2'] = h2Match ? clean(h2Match[1]) : '';

      // 2. A teljes edikt blokk kibontása
      const content = extractEdikt(rawHtml);

      // 3. row elemek kinyerése (span mint mezőnév, p mint érték)
      const rowRegex = /<div[^>]*class=["'][^"']*row[^"']*["'][^>]*>([\s\S]*?)<\/div>/gi;
      let rMatch;
      while ((rMatch = rowRegex.exec(content)) !== null) {
        const span = rMatch[1].match(/<span[^>]*class=["'][^"']*col-sm-3[^"']*["'][^>]*>([\s\S]*?)<\/span>/i);
        const p = rMatch[1].match(/<p[^>]*class=["'][^"']*col-sm-9[^"']*["'][^>]*>([\s\S]*?)<\/p>/i);
        if (span && p) {
          const key = clean(span[1]).replace(/[:]+$/, '');
          if (key) rowObj[key] = clean(p[1]);
        }
      }
      return rowObj;
    } catch (e) {
      return null;
    }
  });

  const batchResults = await Promise.all(promises);
  for (const res of batchResults) {
    if (res) results.push({ json: res });
  }
}

return results;
